export function createDemoScene(t=240,r=21){const e=Math.PI*(3-Math.sqrt(5)),a=new Float32Array(3*t),o=new Float32Array(3*t),s=new Float32Array(t),n=[],h=[];for(let l=0;l<t;l++){const i=1-(l+.5)/t*2,f=Math.sqrt(1-i*i),M=e*l,c=l/Math.max(1,t-1);a.set([Math.cos(M)*f,i,Math.sin(M)*f],3*l),o.set([.2+.7*c,.85-.45*c,.8-.5*c],3*l),s[l]=18+14*Math.sin(.3*l)**2,l>0&&n.push(l-1,l),l+r<t&&n.push(l,l+r),l%12==0&&h.push(l)}return{colors:o,edges:Uint32Array.from(n),labels:{color:"#ffffff",nodes:Uint32Array.from(h),outline:"#0b1220",texts:h.map(t=>`#${t}`)},names:{color:"#ffffff",outline:"#0b1220",texts:Array.from({length:t},(t,r)=>`#${r}`)},paths:[Uint32Array.from(h)],positions:a,sizes:s}}export function createClusteredScene({clusters:t=64,edgesPerNode:r=10,nodes:e=1e5,seed:a=1}={}){let o=a>>>0;const s=()=>{o=o+1831565813>>>0;let t=Math.imul(o^o>>>15,1|o);return t^=t+Math.imul(t^t>>>7,61|t),((t^t>>>14)>>>0)/4294967296},n=Math.PI*(3-Math.sqrt(5)),h=Math.ceil(e/t),l=new Float32Array(3*e),i=new Float32Array(3*e),f=new Float32Array(e),M=new Uint32Array(e),c=e*r,m=new Uint32Array(2*c),u=()=>.12*(s()+s()+s()-1.5),y=t=>[0,8,4].map(r=>{const e=(r+12*t)%12;return.62-.3*Math.max(-1,Math.min(e-3,9-e,1))});for(let r=0;r<e;r++){const e=Math.min(t-1,Math.floor(r/h)),a=1-(e+.5)/t*2,o=Math.sqrt(1-a*a),c=n*e;M[r]=e,l.set([Math.cos(c)*o+u(),a+u(),Math.sin(c)*o+u()],3*r),i.set(y(e/t),3*r),f[r]=3+3*s()}for(let t=0;t<c;t++){const r=Math.floor(s()*e),a=M[r]*h,o=Math.min(h,e-a);m[2*t]=r,m[2*t+1]=s()<.9?a+Math.floor(s()*o):Math.floor(s()*e)}return{clusters:M,colors:i,edges:m,paths:[Uint32Array.from({length:Math.min(10,t)},(r,a)=>Math.min(e-1,7*a%t*h))],positions:l,sizes:f}}